TEMPLATES = {'python': '\nfrom cryptography.hazmat.primitives.asymmetric import rsa, padding\nfrom cryptography.hazmat.primitives import hashes\nkey = rsa.generate_private_key(public_exponent=65537, key_size=2048)\nmessage = b"controlled signature unit"\nsignature = key.sign(message, padding.PSS(mgf=padding.MGF1(hashes.SHA256()), salt_length=padding.PSS.MAX_LENGTH), hashes.SHA256())\nkey.public_key().verify(signature, message, padding.PSS(mgf=padding.MGF1(hashes.SHA256()), salt_length=padding.PSS.MAX_LENGTH), hashes.SHA256())\n', 'java': '\nimport java.security.KeyPairGenerator;\nimport java.security.Signature;\npublic class Main {\n public static void main(String[] args) throws Exception {\n  var generator = KeyPairGenerator.getInstance("RSA"); generator.initialize(2048);\n  var keys = generator.generateKeyPair(); var signer = Signature.getInstance("SHA256withRSA");\n  byte[] msg = "controlled signature unit".getBytes(); signer.initSign(keys.getPrivate()); signer.update(msg);\n  byte[] signature = signer.sign(); signer.initVerify(keys.getPublic()); signer.update(msg);\n  if (!signer.verify(signature)) throw new IllegalStateException();\n }\n}\n', 'go': '\npackage main\nimport ("crypto/rsa"; "crypto/rand"; "crypto/sha256"; "crypto")\nfunc main() {\n key, err := rsa.GenerateKey(rand.Reader, 2048); if err != nil { panic(err) }\n hash := sha256.Sum256([]byte("controlled signature unit"))\n sig, err := rsa.SignPSS(rand.Reader, key, crypto.SHA256, hash[:], nil); if err != nil { panic(err) }\n if err := rsa.VerifyPSS(&key.PublicKey, crypto.SHA256, hash[:], sig, nil); err != nil { panic(err) }\n}\n'}
